// The lens clause (one sentence brief §4): the culture, era, world and region links every module's
// sentence shares, built from `lens.json` (its `sentence`, `menu`, `bands`, `worlds` and `views`
// entries) and `lens-offers.json` (what each module can tell apart, generated by `npm run offers`).
// It is a new way of showing and choosing the state the engines already take: no engine option, no
// stored value and no table changes, and a stored value is always shown and kept (brief rule 4).
// No Obsidian imports.

import { regionPhrase } from "./colonialSentence";
import lensData from "./data/lens.json";
import offersData from "./data/lens-offers.json";
import { LENS_CULTURE_GROUPS, LENS_ERAS } from "./lens";
import { rosterCultures } from "./lensRosters";
import { PLACE_SHAPE_REGIONS } from "./placeShapes";

export type LensField = "culture" | "era" | "world" | "region";

export interface LensChoice {
  id: string;
  label: string;
  title?: string;
  /** Starts a new labelled run of choices in the menu (the culture menu's headings). */
  group?: string;
}

export interface LensSegment {
  field: LensField;
  /** What the sentence shows. */
  text: string;
  /** The tooltip. */
  title: string;
  choices: LensChoice[];
  current: string;
  /** One choice only: drawn as plain text, not a link. */
  fixed?: boolean;
}

/** The lens reading of a stored state: the ids the clause's choices use. */
export interface LensReading {
  culture: string;
  era?: string;
  world?: string;
  region?: string;
}

/** Module-specific rules on the four links, applied on top of the shared clause (brief §3). */
export interface LensRules {
  /** Narrows the world ids a state offers (supernatural courts in a modern world offer contemporary fantasy only). */
  worlds?(state: Record<string, unknown>, ids: string[]): string[];
  /** Knock-on changes after a choice (spacecraft's technology after "modern", supernatural courts' fantastic switch). */
  after?(previous: Record<string, unknown>, next: Record<string, unknown>, field: LensField, id: string): Record<string, unknown>;
}

const RULES: Record<string, LensRules> = {};

/** Registers a module's own rules; each sentence file does it for the rules it keeps. */
export function registerLensRules(moduleKey: string, rules: LensRules): void {
  RULES[moduleKey] = rules;
}

// ── The data ───────────────────────────────────────────────────────────────

interface SentenceEntry {
  family: "A" | "B" | "none";
  fields?: { where?: string | null; culture: string | null; era: string | null; fantastic: string | null; genre: string | null; region: string | null };
  roster?: string | null;
  region?: { group: string; requires: Record<string, string> | null; keepWhenHidden: boolean };
  ownEras?: boolean;
}
interface Band {
  key: string;
  label: string;
  eras: string[];
  genre: string;
}
interface WorldRow {
  key: string;
  eras: string[];
  plain: { label: string; style: string };
  fantastic: { label: string; style: string };
}
interface View {
  label: string;
  culture: string;
  regions: string[];
  default: string;
  fixedText?: string;
}
interface MenuEntry {
  key?: string;
  label?: string | null;
  view?: string;
  /** `colonial`: a colonial tradition offered as a culture (place modules split brief §7). */
  scope?: string;
}
interface Offer {
  family: "A" | "B";
  eras: (string[] | string)[];
  eraRuns?: string[][];
  worlds: Record<string, string[]>;
  views?: string[];
  /** Place modules split brief §7: per where, the colonial cultures whose names differ from General's there. */
  colonial?: Record<string, string[]>;
}

const LENS = lensData as unknown as {
  modules: Record<string, { sentence: SentenceEntry }>;
  bands: Band[];
  worlds: { rows: WorldRow[]; bandRows: Record<string, string> };
  views: Record<string, View>;
  menu: { heading: string | null; entries: MenuEntry[] }[];
  tooltips: { era: string; world: string };
};
const OFFERS = (offersData as unknown as { modules: Record<string, Offer> }).modules;

const REGION_TITLE = "Weights the names towards a region's customs";
const CULTURE_TITLE = "Naming culture: whose customs the names follow";
const ALL = "all";
/** The Celtic entry's menu id while the stored state reads as a view: Celtic, no region. */
export const CELTIC_ANY = "celtic:any";

/** The modules the clause builds for (family A and B). */
export const LENS_VIEW_MODULES: readonly string[] = Object.keys(LENS.modules).filter((m) => LENS.modules[m].sentence.family !== "none");

type State = Record<string, unknown>;

const sentence = (moduleKey: string): SentenceEntry => {
  const entry = LENS.modules[moduleKey]?.sentence;
  if (!entry || entry.family === "none") throw new Error(`lens: “${moduleKey}” has no lens sentence`);
  return entry;
};
const offer = (moduleKey: string): Offer => {
  const found = OFFERS[moduleKey];
  if (!found) throw new Error(`lens: “${moduleKey}” is not in lens-offers.json (run npm run offers)`);
  return found;
};

const eraLabel = (code: string): string => LENS_ERAS.find((e) => e.code === code)?.label ?? code;
const REALM_ERA_LABELS: Record<string, string> = { ancient: "ancient", medieval: "medieval", earlyModern: "early modern", modern: "modern", nearFuture: "near future", interstellar: "interstellar" };
/** Realms' own era values, and the genre each reads as (§7.3). */
const REALM_ERA_GENRE: Record<string, string> = { ancient: "fantasy", medieval: "fantasy", earlyModern: "fantasy", modern: "modern", nearFuture: "scifi", interstellar: "scifi" };

const get = (state: State, field: string | null | undefined): unknown => (field ? state[field] : undefined);

// ── Culture and region ─────────────────────────────────────────────────────

const britishKeys = (): readonly string[] => LENS_CULTURE_GROUPS.british.cultures;

/** Whether the region link shows: a British culture, and whatever else the module needs (wild lands: home country). */
function regionShown(entry: SentenceEntry, state: State): boolean {
  const f = entry.fields;
  if (!f?.region || !entry.region) return false;
  if (!britishKeys().includes(String(get(state, f.culture)))) return false;
  const requires = entry.region.requires;
  return !requires || Object.entries(requires).every(([field, value]) => state[field] === value);
}

/** The view a stored (celtic, region) reads as, if any (§6.3). */
function viewOf(entry: SentenceEntry, state: State): string | undefined {
  if (!regionShown(entry, state)) return undefined;
  if (get(state, entry.fields!.culture) !== "celtic") return undefined;
  const region = get(state, entry.fields!.region) as string | undefined;
  if (!region) return undefined;
  return Object.keys(LENS.views).find((v) => LENS.views[v].regions.includes(region));
}

const viewsOffered = (moduleKey: string): string[] => offer(moduleKey).views ?? [];

/** Every culture the module offers today, plus the views the probe found, under the lens headings. */
function cultureChoices(moduleKey: string, entry: SentenceEntry, current: string, where?: string): LensChoice[] {
  const roster = new Map(rosterCultures(entry.roster!).map((c) => [c.key, c.label]));
  const views = new Set([...viewsOffered(moduleKey), ...(LENS.views[current] ? [current] : [])]);
  const out: LensChoice[] = [];
  const placed = new Set<string>();
  for (const block of LENS.menu) {
    let first = true;
    for (const e of block.entries) {
      let id: string | undefined;
      let label: string | undefined;
      if (e.view) {
        if (!views.has(e.view)) continue;
        id = e.view;
        label = LENS.views[e.view].label;
      } else if (e.scope === "colonial" && e.key) {
        // §7: a colonial tradition is a culture only where the where link is newly explored or settled and the probe found it differs there; a stored one is always shown.
        const offered = where && where !== "home" ? offer(moduleKey).colonial?.[where] ?? [] : [];
        if (!offered.includes(e.key) && current !== e.key) continue;
        id = e.key;
        label = e.label ?? e.key;
      } else if (e.key && roster.has(e.key)) {
        id = e.key;
        label = e.label ?? roster.get(e.key)!;
      }
      if (!id || !label) continue;
      placed.add(id);
      out.push({ id, label, ...(first && block.heading ? { group: block.heading } : {}) });
      first = false;
    }
  }
  // From a view, the Celtic entry means "Celtic, all of Britain": its menu id says so, since choosing the stored culture key itself changes nothing (a preset's own mapping does that and must keep its region).
  if (LENS.views[current]) for (const c of out) if (c.id === "celtic") c.id = CELTIC_ANY;
  // A key the module has and the lens menu doesn't list keeps its own label, after the rest.
  for (const [key, label] of roster) if (!placed.has(key)) out.push({ id: key, label });
  // Rule 4: a stored culture the module doesn't list is still shown, and kept.
  if (!out.some((c) => c.id === current)) out.push({ id: current, label: current });
  return out;
}

const regionLabel = (code: string | undefined): string => (code ? `in ${regionPhrase(code)}` : "across all of Britain");

const regionChoices = (codes: readonly string[], withAll: boolean): LensChoice[] => [
  ...(withAll ? [{ id: ALL, label: regionLabel(undefined) }] : []),
  ...PLACE_SHAPE_REGIONS.filter((r) => codes.includes(r.code)).map((r) => ({ id: r.code, label: regionLabel(r.code), title: r.counties })),
];

function regionSegment(moduleKey: string, entry: SentenceEntry, state: State, culture: string, opts: LensOptions): LensSegment | undefined {
  if (!regionShown(entry, state)) return undefined;
  const stored = get(state, entry.fields!.region) as string | undefined;
  const title = opts.regionTitle ?? REGION_TITLE;
  const view = LENS.views[culture];
  if (view && culture !== "scottish") {
    // Welsh and Cornish: one region, drawn as plain text.
    return { field: "region", text: view.fixedText ?? regionLabel(view.regions[0]), title, choices: regionChoices(view.regions, false), current: view.regions[0], fixed: true };
  }
  if (view) {
    const codes = [...view.regions];
    const current = stored && codes.includes(stored) ? stored : view.default;
    return { field: "region", text: regionLabel(current), title, choices: regionChoices(codes, false), current };
  }
  let codes = PLACE_SHAPE_REGIONS.map((r) => r.code);
  if (culture === "celtic") {
    // Where a view is offered, Celtic's own menu no longer lists that view's regions.
    const dropped = new Set(viewsOffered(moduleKey).flatMap((v) => LENS.views[v].regions));
    codes = codes.filter((c) => !dropped.has(c) || c === stored);
  }
  const choices = regionChoices(codes, true);
  // Rule 4: a stored region the menu doesn't list is still shown.
  if (stored && !choices.some((c) => c.id === stored)) choices.push(...regionChoices([stored], false));
  return { field: "region", text: regionLabel(stored), title, choices, current: stored ?? ALL };
}

// ── Era and world ──────────────────────────────────────────────────────────

const bandOfGenre = (genre: unknown): Band | undefined => LENS.bands.find((b) => b.genre === genre);

function runLabel(run: string[]): string {
  if (run.length === 1) return eraLabel(run[0]);
  for (const band of LENS.bands) if (band.eras.length === run.length && band.eras.every((e, i) => run[i] === e)) return band.label;
  return `${eraLabel(run[0])} to ${eraLabel(run[run.length - 1])}`;
}
const runId = (run: string[]): string => run.join("-");

/** Family A: the runs of eras the probe found (adjacent eras that never differ are one). */
const runsOf = (moduleKey: string): string[][] => offer(moduleKey).eras as string[][];

/** Whether an era id (a run's id, or one era code) is one the module's era link can hold. Realms' own eras and family B bands are always their own. */
export function eraOffered(moduleKey: string, id: string): boolean {
  const entry = sentence(moduleKey);
  if (entry.ownEras || entry.family === "B") return true;
  const codes = id.split("-");
  return runsOf(moduleKey).some((r) => codes.every((c) => r.includes(c)));
}

/** The era choices and the stored era's id, or undefined when the module has no era link. */
function eraModel(moduleKey: string, entry: SentenceEntry, state: State): { choices: LensChoice[]; current: string } | undefined {
  const f = entry.fields!;
  if (entry.ownEras) {
    // Realms: the six eras it has as now; the world link reads the genre.
    const o = offer(moduleKey);
    const eras = (o.eraRuns ?? []).map((r) => r[0]);
    const current = String(get(state, f.era) ?? eras[0]);
    const choices = eras.map((e) => ({ id: e, label: REALM_ERA_LABELS[e] ?? e }));
    if (!eras.includes(current)) choices.push({ id: current, label: REALM_ERA_LABELS[current] ?? current });
    return { choices, current };
  }
  if (entry.family === "A") {
    const runs = runsOf(moduleKey);
    if (runs.length < 2) return undefined;
    const era = String(get(state, f.era));
    const run = runs.find((r) => r.includes(era));
    const choices = runs.map((r) => ({ id: runId(r), label: runLabel(r) }));
    // Rule 4: a stored era no run holds is still shown.
    if (!run) choices.push({ id: era, label: eraLabel(era) });
    return { choices, current: run ? runId(run) : era };
  }
  // Family B: the three bands, each stored as a genre.
  const offered = (offer(moduleKey).eras as string[]).map((k) => LENS.bands.find((b) => b.key === k)!).filter(Boolean);
  const band = bandOfGenre(get(state, f.genre)) ?? offered[0];
  const choices = offered.map((b) => ({ id: b.key, label: b.label }));
  if (!choices.some((c) => c.id === band.key)) choices.push({ id: band.key, label: band.label });
  return { choices, current: band.key };
}

/** The world row (§7.1) the stored era or band sits in. */
function worldRow(entry: SentenceEntry, state: State): WorldRow {
  const f = entry.fields!;
  if (entry.family === "B") {
    const band = bandOfGenre(get(state, f.genre)) ?? LENS.bands[0];
    return LENS.worlds.rows.find((r) => r.key === LENS.worlds.bandRows[band.key])!;
  }
  const era = String(get(state, f.era));
  return LENS.worlds.rows.find((r) => r.eras.includes(era)) ?? LENS.worlds.rows[0];
}

/** The probe's offered worlds for the stored era (family A) or band (family B). */
function offeredWorlds(moduleKey: string, entry: SentenceEntry, state: State): string[] {
  const f = entry.fields!;
  const o = offer(moduleKey);
  const key = entry.family === "B" ? (bandOfGenre(get(state, f.genre)) ?? LENS.bands[0]).key : String(get(state, f.era));
  return o.worlds[key] ?? ["plain"];
}

/** Whether a stored state reads as a science fiction genre (family B's future band: one setting, no fantastic switch). */
const isFutureGenre = (entry: SentenceEntry, state: State): boolean => entry.family === "B" && get(state, entry.fields!.genre) === "scifi";

function worldSegment(moduleKey: string, entry: SentenceEntry, state: State): LensSegment | undefined {
  const f = entry.fields!;
  if (!f.fantastic) return undefined;
  const row = worldRow(entry, state);
  const stored = get(state, f.fantastic) === true ? "fantastic" : "plain";
  const future = isFutureGenre(entry, state);
  // A science fiction genre has no fantastic setting today: one plain choice, whatever the switch holds.
  const current = future ? "plain" : stored;
  let ids = future ? ["plain"] : offeredWorlds(moduleKey, entry, state);
  ids = RULES[moduleKey]?.worlds?.(state, [...ids]) ?? ids;
  // Rule 4: the stored world is always among the choices.
  if (!ids.includes(current)) ids = [...ids, current].sort((a, b) => (a === "plain" ? -1 : b === "plain" ? 1 : 0));
  const choices = ids.map((id) => ({ id, label: row[id as "plain" | "fantastic"].label }));
  return {
    field: "world",
    text: row[current as "plain" | "fantastic"].label,
    title: LENS.tooltips.world,
    choices,
    current,
    ...(choices.length === 1 ? { fixed: true } : {}),
  };
}

// ── The clause ─────────────────────────────────────────────────────────────

export interface LensOptions {
  cultureTitle?: string;
  regionTitle?: string;
}

/** The four links for a module in its present state; a module without one omits it. Sentence order is the caller's. */
export function lensClause(moduleKey: string, state: object, opts: LensOptions = {}): Partial<Record<LensField, LensSegment>> {
  const entry = sentence(moduleKey);
  const s = state as State;
  const f = entry.fields!;
  const out: Partial<Record<LensField, LensSegment>> = {};
  let culture = "";
  if (f.culture) {
    culture = viewOf(entry, s) ?? String(get(s, f.culture));
    const choices = cultureChoices(moduleKey, entry, culture, f.where ? String(get(s, f.where) ?? "") || undefined : undefined);
    out.culture = { field: "culture", text: choices.find((c) => c.id === culture)!.label, title: opts.cultureTitle ?? CULTURE_TITLE, choices, current: culture };
  }
  if (f.era || f.genre) {
    const era = eraModel(moduleKey, entry, s);
    if (era) out.era = { field: "era", text: era.choices.find((c) => c.id === era.current)!.label, title: LENS.tooltips.era, choices: era.choices, current: era.current };
  }
  const world = worldSegment(moduleKey, entry, s);
  if (world) out.world = world;
  if (f.culture) {
    const region = regionSegment(moduleKey, entry, s, culture, opts);
    if (region) out.region = region;
  }
  return out;
}

/** The lens reading of a stored state, for history rows, preset descriptions and storyForge. */
export function lensReading(moduleKey: string, state: object): LensReading {
  const clause = lensClause(moduleKey, state);
  const entry = sentence(moduleKey);
  const s = state as State;
  const f = entry.fields!;
  return {
    culture: clause.culture?.current ?? (f.culture ? String(get(s, f.culture)) : ""),
    ...(clause.era ? { era: clause.era.current } : {}),
    ...(clause.world ? { world: clause.world.current } : {}),
    ...(clause.region ? { region: clause.region.current } : {}),
  };
}

/** Sets a field only when it changes, so choosing what a state already holds gives the identical state back. */
function put(state: State, key: string, value: unknown): void {
  if (state[key] !== value) state[key] = value;
}

/** The state after one choice. Module knock-ons beyond the four links (kinds, scales, technology) stay in each module, or in its registered rules. */
export function applyLensChoice<S extends object>(moduleKey: string, state: S, field: LensField, id: string): S {
  const entry = sentence(moduleKey);
  const f = entry.fields!;
  const previous = state as State;
  const next: State = { ...previous };
  switch (field) {
    case "culture": {
      if (!f.culture) break;
      const before = viewOf(entry, previous);
      if (id === CELTIC_ANY) {
        put(next, f.culture, "celtic");
        if (f.region) put(next, f.region, undefined);
        break;
      }
      const view = LENS.views[id];
      if (view) {
        put(next, f.culture, view.culture);
        if (f.region) {
          const stored = previous[f.region] as string | undefined;
          put(next, f.region, stored && view.regions.includes(stored) ? stored : view.default);
        }
      } else {
        put(next, f.culture, id);
        // Changing culture away from a view clears the region; so does Celtic itself when it was a view.
        if (before && f.region && before !== id && id !== get(previous, f.culture)) put(next, f.region, undefined);
      }
      break;
    }
    case "era": {
      if (entry.ownEras) {
        // A stored era and genre that disagree are shown as they are; choosing the same era leaves them, choosing another re-reads the genre.
        if (f.era && previous[f.era] !== id) {
          put(next, f.era, id);
          if (f.genre && REALM_ERA_GENRE[id]) put(next, f.genre, REALM_ERA_GENRE[id]);
        }
      } else if (entry.family === "A") {
        const run = id.split("-");
        const stored = String(previous[f.era!]);
        put(next, f.era!, run.includes(stored) ? stored : run.includes("MD") ? "MD" : run[0]);
      } else {
        const band = LENS.bands.find((b) => b.key === id);
        if (band && f.genre) put(next, f.genre, band.genre);
      }
      break;
    }
    case "world": {
      if (!f.fantastic) break;
      // Science fiction has no fantastic switch: leave it as stored.
      if (isFutureGenre(entry, previous)) break;
      put(next, f.fantastic, id === "fantastic");
      break;
    }
    case "region": {
      if (!f.region) break;
      put(next, f.region, id === ALL ? undefined : id);
      break;
    }
  }
  // The region link hides away from the British cultures; most modules then drop the value, wild lands keep it.
  if (f.region && entry.region && !entry.region.keepWhenHidden && !regionShown(entry, next)) put(next, f.region, undefined);
  const after = RULES[moduleKey]?.after;
  return (after ? after(previous, next, field, id) : next) as S;
}
